# -----------------------------
# 2a. Calendar-time backstop for month-resolution public datasets
# -----------------------------
# This repository publishes calendar time at month resolution (delivery_month,
# delivery_year_quarter, delivery_month_numeric) to reduce re-identification
# risk. The downstream pipeline expects a day-level `delivery_date` column.
# When the raw file does not carry a day-level `delivery_date_iso` field but
# does carry `delivery_month` (YYYY-MM), synthesize delivery_date_iso as the
# 15th of the stated month as a neutral mid-month anchor for the natural
# cubic spline. Day-of-month variation is absent by design, but with df = 3
# the spline is effectively a smooth function of months-since-anchor and the
# estimates are statistically equivalent to the day-level model at the
# precision reported.
if (!"delivery_date_iso" %in% names(raw) && "delivery_month" %in% names(raw)) {
  log_step("delivery_date_iso absent; synthesizing day-level dates from delivery_month (15th-of-month anchor) for spline construction.")
  raw <- raw %>%
    mutate(
      delivery_date_iso = if_else(
        !is.na(delivery_month) & nzchar(as.character(delivery_month)),
        paste0(as.character(delivery_month), "-15"),
        NA_character_
      )
    )
}

