has_2plus <- function(x) n_distinct(x[!is.na(x)]) >= 2
base_covariates <- c("pre_delivery_hemoglobin_g_dl", "body_mass_index_kg_m2", "parity", "delivery_mode", "plurality_group", "grand_multiparity", "iron_use_during_pregnancy", "iv_ferric_carboxymaltose_use_during_pregnancy", "maternal_comorbidity_any", "pregnancy_complication_any", "delivery_date_numeric")
