log_step("Running matching sensitivity")
match_results <- tibble()
try({
  m_needed <- unique(c(PRIMARY_EXPOSURE, needed_vars_for_terms(ps_terms, dat), binary_outcomes, continuous_outcomes))
  md <- dat %>% select(any_of(m_needed)) %>% drop_na(any_of(c(PRIMARY_EXPOSURE, needed_vars_for_terms(ps_terms, dat))))
  if (nrow(md) > 0 && has_2plus(md[[PRIMARY_EXPOSURE]])) {
    mfit <- MatchIt::matchit(build_formula(PRIMARY_EXPOSURE, ps_terms, md), data = md, method = "nearest", ratio = 1, caliper = 0.2)
    mdat <- MatchIt::match.data(mfit)
    write_text(capture.output(summary(mfit)), file.path(OUTPUT_DIR, "04_matching_summary.txt"))
    tmp <- list()
    for (y in binary_outcomes) tmp[[y]] <- fit_poisson_rr(mdat, y, PRIMARY_EXPOSURE, character(), "matched_modified_poisson_RR")
    for (y in continuous_outcomes) tmp[[y]] <- fit_linear_beta(mdat, y, PRIMARY_EXPOSURE, character(), "matched_linear_beta")
    match_results <- standardize_result_table(bind_rows(tmp))
  }
}, silent = TRUE)
safe_write_csv(match_results, file.path(OUTPUT_DIR, "04_matching_results_all_terms.csv"))
safe_write_csv(safe_term_filter(match_results, PRIMARY_EXPOSURE), file.path(OUTPUT_DIR, "04_matching_results_exposure_terms.csv"))

