for (y in continuous_outcomes) sens_results[[paste("dose", y)]] <- fit_linear_beta(dat %>% mutate(cord_delay_min = cord_clamping_delay_seconds / 60), y, "cord_delay_min", model_covariates, "dose_per_minute_beta")
